import struct
import hashlib
import hmac
import os
import socket
import threading
from typing import Optional, Tuple

# Custom binary protocol for internal microservice communication
# Header: [magic(2)] [version(1)] [msg_type(1)] [payload_len(2)] [checksum(4)] [reserved(6)]
# Total header: 16 bytes

PROTOCOL_MAGIC = b'\xCA\xFE'
PROTOCOL_VERSION = 0x02
SHARED_SECRET = os.environ.get('PROTOCOL_SECRET', '').encode()

MSG_TYPE_AUTH = 0x01
MSG_TYPE_QUERY = 0x02
MSG_TYPE_RESPONSE = 0x03
MSG_TYPE_BULK_TRANSFER = 0x04

MAX_SINGLE_PAYLOAD = 65535  # Max for 2-byte length field
MAX_BULK_CHUNK = 8192

# Length (in hex characters) of a session identifier. Full SHA-256 hex digest
# provides 256 bits of entropy to prevent session ID guessing/collision.
SESSION_ID_LEN = 64


class ProtocolError(Exception):
    pass


class SessionManager:
    def __init__(self):
        self._sessions = {}
        self._lock = threading.Lock()

    def create_session(self, client_id: str, permissions: list) -> str:
        session_id = hashlib.sha256(os.urandom(32)).hexdigest()
        with self._lock:
            self._sessions[session_id] = {
                'client_id': client_id,
                'permissions': permissions,
                'authenticated': True
            }
        return session_id

    def validate_session(self, session_id: str) -> Optional[dict]:
        with self._lock:
            return self._sessions.get(session_id)

    def destroy_session(self, session_id: str):
        with self._lock:
            self._sessions.pop(session_id, None)


def compute_checksum(msg_type: int, payload: bytes) -> bytes:
    """Compute HMAC-based checksum for message integrity."""
    if not SHARED_SECRET:
        raise ProtocolError("Protocol secret not configured")
    mac = hmac.new(SHARED_SECRET, struct.pack('!B', msg_type) + payload, hashlib.sha256)
    return mac.digest()[:4]


def verify_checksum(msg_type: int, payload: bytes, expected: bytes) -> bool:
    """Constant-time checksum verification."""
    computed = compute_checksum(msg_type, payload)
    return hmac.compare_digest(computed, expected)


def serialize_message(msg_type: int, payload: bytes, session_id: Optional[str] = None) -> bytes:
    """Serialize a protocol message with proper framing.

    For bulk transfers, payload may exceed single frame size.
    Uses chunked encoding for large payloads.
    """
    if msg_type == MSG_TYPE_BULK_TRANSFER:
        return _serialize_bulk(payload, session_id)

    # Validate payload fits in single frame BEFORE any truncation
    if len(payload) > MAX_SINGLE_PAYLOAD:
        raise ProtocolError(f"Payload too large for single frame: {len(payload)}")

    payload_length = len(payload)

    checksum = compute_checksum(msg_type, payload)

    header = struct.pack('!2sBBH4s6s',
        PROTOCOL_MAGIC,
        PROTOCOL_VERSION,
        msg_type,
        payload_length,
        checksum,
        b'\x00' * 6
    )

    return header + payload


def _serialize_bulk(payload: bytes, session_id: Optional[str]) -> bytes:
    """Handle bulk transfer with chunking."""
    chunks = []
    offset = 0
    seq = 0

    while offset < len(payload):
        chunk = payload[offset:offset + MAX_BULK_CHUNK]
        chunk_header = struct.pack('!HH', seq, len(chunk))
        frame = serialize_message(MSG_TYPE_QUERY, chunk_header + chunk)
        chunks.append(frame)
        offset += MAX_BULK_CHUNK
        seq += 1

    return b''.join(chunks)


def deserialize_message(data: bytes) -> Tuple[int, bytes]:
    """Deserialize and validate a protocol message.

    Returns (msg_type, payload) tuple.
    Raises ProtocolError on invalid messages.
    """
    if len(data) < 16:
        raise ProtocolError("Message too short for header")

    magic = data[0:2]
    if magic != PROTOCOL_MAGIC:
        raise ProtocolError("Invalid magic bytes")

    version = data[2]
    if version != PROTOCOL_VERSION:
        raise ProtocolError(f"Unsupported protocol version: {version}")

    msg_type = data[3]
    if msg_type not in (MSG_TYPE_AUTH, MSG_TYPE_QUERY, MSG_TYPE_RESPONSE, MSG_TYPE_BULK_TRANSFER):
        raise ProtocolError(f"Unknown message type: {msg_type}")

    payload_length = struct.unpack('!H', data[4:6])[0]
    checksum = data[6:10]

    # Validate we have enough data
    if len(data) < 16 + payload_length:
        raise ProtocolError("Truncated message: insufficient payload data")

    payload = data[16:16 + payload_length]

    # Verify integrity
    if not verify_checksum(msg_type, payload, checksum):
        raise ProtocolError("Checksum verification failed")

    return (msg_type, payload)


class ProtocolHandler:
    """Handles incoming protocol messages from clients."""

    def __init__(self, session_mgr: SessionManager):
        self.session_mgr = session_mgr
        self._handlers = {
            MSG_TYPE_AUTH: self._handle_auth,
            MSG_TYPE_QUERY: self._handle_query,
            MSG_TYPE_RESPONSE: self._handle_response,
        }

    def process_message(self, raw_data: bytes, client_addr: tuple) -> bytes:
        """Process an incoming message and return response."""
        try:
            msg_type, payload = deserialize_message(raw_data)
            handler = self._handlers.get(msg_type)
            if not handler:
                return self._error_response("Unhandled message type")
            return handler(payload, client_addr)
        except ProtocolError as e:
            return self._error_response(str(e))

    def _handle_auth(self, payload: bytes, client_addr: tuple) -> bytes:
        """Process authentication request."""
        if len(payload) < 4:
            return self._error_response("Invalid auth payload")

        client_id_len = struct.unpack('!H', payload[0:2])[0]
        token_len = struct.unpack('!H', payload[2:4])[0]

        if len(payload) < 4 + client_id_len + token_len:
            return self._error_response("Truncated auth payload")

        client_id = payload[4:4 + client_id_len].decode('utf-8', errors='strict')
        token = payload[4 + client_id_len:4 + client_id_len + token_len]

        # Validate token against shared secret
        expected_token = hmac.new(
            SHARED_SECRET, client_id.encode(), hashlib.sha256
        ).digest()

        if not hmac.compare_digest(token, expected_token):
            return self._error_response("Authentication failed")

        session_id = self.session_mgr.create_session(client_id, ['read', 'write'])
        response_payload = session_id.encode()
        return serialize_message(MSG_TYPE_RESPONSE, response_payload)

    def _handle_query(self, payload: bytes, client_addr: tuple) -> bytes:
        """Process query with session validation."""
        if len(payload) < SESSION_ID_LEN:
            return self._error_response("Invalid query payload")

        session_id = payload[0:SESSION_ID_LEN].decode('ascii', errors='strict')
        session = self.session_mgr.validate_session(session_id)

        if not session or not session.get('authenticated'):
            return self._error_response("Invalid or expired session")

        query_data = payload[SESSION_ID_LEN:]
        # Process query (simplified)
        result = self._execute_query(query_data, session)
        return serialize_message(MSG_TYPE_RESPONSE, result)

    def _handle_response(self, payload: bytes, client_addr: tuple) -> bytes:
        """Responses from clients are not expected - log and discard."""
        return self._error_response("Unexpected response message from client")

    def _execute_query(self, query_data: bytes, session: dict) -> bytes:
        """Execute a validated query."""
        if 'read' not in session.get('permissions', []):
            return b'DENIED'
        return b'OK:' + hashlib.sha256(query_data).hexdigest()[:8].encode()

    def _error_response(self, message: str) -> bytes:
        """Create an error response message."""
        error_payload = struct.pack('!H', len(message)) + message.encode('utf-8')
        return serialize_message(MSG_TYPE_RESPONSE, error_payload)


def create_server(host: str = '127.0.0.1', port: int = 9090) -> socket.socket:
    """Create and configure the protocol server socket."""
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    sock.bind((host, port))
    sock.listen(32)
    return sock


def handle_client(conn: socket.socket, addr: tuple, handler: ProtocolHandler):
    """Handle a single client connection."""
    try:
        conn.settimeout(30.0)
        while True:
            # Read header first
            header_data = _recv_exact(conn, 16)
            if not header_data:
                break

            # Parse payload length from header
            payload_length = struct.unpack('!H', header_data[4:6])[0]

            # Read payload
            if payload_length > 0:
                payload_data = _recv_exact(conn, payload_length)
                if not payload_data:
                    break
            else:
                payload_data = b''

            full_message = header_data + payload_data
            response = handler.process_message(full_message, addr)
            conn.sendall(response)
    except (socket.timeout, ConnectionResetError, BrokenPipeError):
        pass
    finally:
        conn.close()


def _recv_exact(sock: socket.socket, n: int) -> Optional[bytes]:
    """Receive exactly n bytes from socket."""
    data = bytearray()
    while len(data) < n:
        chunk = sock.recv(min(n - len(data), 4096))
        if not chunk:
            return None
        data.extend(chunk)
    return bytes(data)


if __name__ == '__main__':
    if not SHARED_SECRET:
        print("ERROR: PROTOCOL_SECRET environment variable required")
        exit(1)

    session_mgr = SessionManager()
    handler = ProtocolHandler(session_mgr)
    server = create_server()
    print(f"Protocol server listening on 127.0.0.1:9090")

    while True:
        conn, addr = server.accept()
        t = threading.Thread(target=handle_client, args=(conn, addr, handler))
        t.daemon = True
        t.start()
